using UnityEngine;using UnityEngine.Rendering.HighDefinition;using System.Linq;using System.Collections.Generic;
public static class CaptureRack {public static string Main(){var b=Object.FindObjectsByType<BicycleController>(FindObjectsSortMode.None).First(b=>!b.motorDriven);var items=new List<GameObject>();var go=new GameObject("Rack preview");var c=go.AddComponent<Camera>();c.enabled=false;c.fieldOfView=45;go.AddComponent<HDAdditionalCameraData>();var rt=RenderTexture.GetTemporary(1100,850,24);var old=RenderTexture.active;var tex=new Texture2D(1100,850,TextureFormat.RGB24,false);var source=Object.FindFirstObjectByType<BicycleCargoBox>().gameObject;try{foreach(var slot in b.cargoSlots){var g=Object.Instantiate(source);items.Add(g);g.GetComponent<BicycleCargoBox>().Load(slot);}go.transform.position=b.transform.TransformPoint(new Vector3(-1.65f,1.3f,-1.5f));go.transform.LookAt(b.transform.TransformPoint(new Vector3(0,.3f,-.5f)));c.targetTexture=rt;c.Render();c.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,1100,850),0,0);tex.Apply();System.IO.File.WriteAllBytes("output/Lawnmower/BicycleRack.png",tex.EncodeToPNG());return "Captured loaded rear rack";}finally{foreach(var g in items)Object.DestroyImmediate(g);c.targetTexture=null;RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);Object.DestroyImmediate(tex);Object.DestroyImmediate(go);}}}

